mutation volumeCreate($input: VolumeCreateInput!) {
  volumeCreate(input: $input) {
    createdAt
    id
    name
    projectId
    volumeInstances(first: 10) {
      edges {
        node {
          createdAt
          currentSizeMB
          deletedAt
          environmentId
          id
          isPendingDeletion
          mountPath
          region
          serviceId
          sizeMB
          state
          volume {
            createdAt
            id
            name
            projectId
          }
          volumeId
        }
      }
    }
  }
}
